"""Builds queue/<YYYY-MM-DD>-<HH>.json files read by the Make scenarios.
Slot 18 = posters (photo), slot 20 = reels. Each file is a JSON array of posts."""
import json, os

BASE = 'https://raw.githubusercontent.com/zoecher9631/goglhamedia/main/'
HT_MEME = '#غوغلها #ميمز_سورية #جيمرز'
TIP_TAGS = '#نصيحة_مستر_غو #جيل_واعي #غوغلها'

def reel(f, caption, yt_title, cat='23', platforms='ig,fb,yt'):
    return dict(kind='reel', media_url=BASE + 'reels/' + f, caption=caption, yt_title=yt_title,
                yt_category=cat, file_name=f, platforms=platforms)

def photo(f, caption, platforms='ig,fb'):
    return dict(kind='photo', media_url=BASE + 'posters/' + f, caption=caption, file_name=f, platforms=platforms)

def tip(n, cat, text):
    return photo(f'MisterGo_Tip_{n:02d}.jpg', f'نصيحة اليوم من مستر غو 🎩 ({cat})\n{text}\n\nشارك النصيحة مع حدا بتحبو 💛\n{TIP_TAGS}')

Q = {}
def add(date, slot, post):
    # December: Instagram/Threads/Pinterest/TikTok go through Metricool, Make does Facebook + YouTube only
    if date >= '2026-12-01':
        post = dict(post, platforms='fb,yt' if post['kind'] == 'reel' else 'fb')
    Q.setdefault(f'{date}-{slot}', []).append(post)

